<section class="container page-heading"><span class="section-kicker">Transaksi</span><h1>Pembayaran & verifikasi</h1><p>Setiap bukti pembayaran ditinjau admin. Keputusan verifikasi dan catatan disimpan agar perubahan dapat ditelusuri.</p></section>
<section class="container admin-page"><div class="surface"><div class="surface-pad page-toolbar"><div><h2 class="h5 mb-1">Daftar pembayaran</h2><p class="form-note mb-0">Hanya pembayaran berstatus disetujui yang dihitung sebagai pendapatan.</p></div><form method="get" class="d-flex gap-2"><input type="hidden" name="r" value="admin-payments"><select class="form-select form-select-sm" name="status"><option value="">Semua status</option><?php foreach(['menunggu','disetujui','ditolak'] as $s): ?><option value="<?= e($s) ?>" <?= $filterStatus===$s?'selected':'' ?>><?= e(status_label($s)) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-dark">Filter</button></form></div><div class="table-wrap"><table class="table"><thead><tr><th>Transaksi</th><th>Pelanggan / reservasi</th><th>Nominal</th><th>Bukti / status</th><th>Verifikasi</th></tr></thead><tbody><?php foreach($payments as $p): ?><tr><td><strong>#<?= (int)$p['id_transaksi'] ?></strong><span class="subtext"><?= e(date_id($p['tanggal_bayar'],true)) ?></span><span class="subtext"><?= e(ucfirst($p['jenis_pembayaran'])) ?></span></td><td><?= e($p['nama_pelanggan']) ?><span class="subtext"><?= e($p['kode_reservasi']) ?> · <?= e($p['nama_paket']) ?></span></td><td><strong><?= money($p['nominal']) ?></strong></td><td><a class="text-link" target="_blank" rel="noopener" href="<?= e(url('proof',['id'=>$p['id_transaksi']])) ?>">Lihat bukti ↗</a><div class="mt-2"><span class="badge-status <?= e(status_class($p['status_verifikasi'])) ?>"><?= e(status_label($p['status_verifikasi'])) ?></span></div><?php if ($p['catatan_verifikasi']): ?><span class="subtext"><?= e($p['catatan_verifikasi']) ?></span><?php endif; ?></td><td style="min-width:250px"><?php if($p['status_verifikasi']==='menunggu'): ?><form method="post" action="<?= e(url('admin-payment-action')) ?>"><?= csrf_field() ?><input type="hidden" name="id_transaksi" value="<?= (int)$p['id_transaksi'] ?>"><textarea class="form-control form-control-sm mb-2" name="catatan_verifikasi" rows="2" maxlength="500" placeholder="Catatan (wajib bila menolak)"></textarea><div class="small-actions"><button class="btn btn-sm btn-success" name="keputusan" value="disetujui" type="submit" data-confirm="Setujui pembayaran #<?= (int)$p['id_transaksi'] ?>?">Setujui</button><button class="btn btn-sm btn-outline-danger" name="keputusan" value="ditolak" type="submit" data-confirm="Tolak pembayaran ini?">Tolak</button></div></form><?php else: ?><small class="muted">Diverifikasi oleh <?= e($p['nama_verifikator'] ?? 'Admin') ?></small><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$payments): ?><tr><td colspan="5" class="muted text-center py-5">Belum ada pembayaran pada filter ini.</td></tr><?php endif; ?></tbody></table></div></div></section>
